INSERT INTO homepage_sections (tenant_id, section_type, title, subtitle, content, settings, sort_order, is_visible) VALUES ('8c4ffd3a-a4d7-50ee-8d27-72fe909bf5cb', 'text_image', 'Uit eigen atelier', null, '{"text": "We maken elke crème in kleine batches, met plantaardige oliën en zo weinig mogelijk ingrediënten. Geschikt voor de gevoelige huid.", "image_url": "", "image_position": "right", "button_text": "Bekijk alles", "button_link": "/producten"}'::jsonb, '{}'::jsonb, 3, true);
INSERT INTO homepage_sections (tenant_id, section_type, title, subtitle, content, settings, sort_order, is_visible) VALUES ('8c4ffd3a-a4d7-50ee-8d27-72fe909bf5cb', 'faq', 'Goed om te weten', null, '{"items": [{"question": "Is dit geschikt voor een gevoelige huid?", "answer": "Ja, al onze producten zijn parfumvrij en dermatologisch getest."}, {"question": "Hoe lang blijft een crème goed?", "answer": "Twaalf maanden na opening. De datum staat op de verpakking."}, {"question": "Is dit een echte winkel?", "answer": "Nee, dit is een demowinkel van SellQo. Je kan alles uitproberen, ook afrekenen, maar er wordt niets verzonden of aangerekend."}]}'::jsonb, '{}'::jsonb, 4, true);